from collections import Counter

class Solution:
    def equalPairs(self, grid: list[list[int]]) -> int:
        row_counts = Counter(tuple(row) for row in grid)
        result = 0
        n = len(grid)
        for c in range(n):
            col = tuple(grid[r][c] for r in range(n))
            result += row_counts[col]
        return result

